import java.util.Scanner;
public class JRepeatedSequence2 {
	public static void main(String[] args){
		//Khatwa 1: Iqra al-adad al-kamil N alladhi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil al-adad al-kamil N: ");
		int N = scan.nextInt();
		scan.close();
		//Khatwa 2: Taba'a N arqam mufasilah bimasafa
		for (int i = 1; i <= N; i++) {
			//Khatwa 2.1: Taba al-raqam al-i i marrat
		    for (int j = 1; j <= i; j++) {
		        System.out.print(i);    
		    } 
		    System.out.print(" ");
		}
	}
}
